function importScriptProperties() {

  // Inser here the ID of sheet X1- Configurations
  const sheetId = "1b0uy_RZxOba3gf82VxpUZJtRpmRIyEERR4ZDwLG9hkM";
  const sheetName = "Script Properties";

  const sheet = SpreadsheetApp.openById(sheetId).getSheetByName(sheetName);

  // Read D5:E(lastRow)
  const startRow = 5;
  const range = sheet.getRange(startRow, 3, sheet.getLastRow() - startRow + 1, 2);
  const data = range.getValues();  // array of [key, value]

  const scriptProps = PropertiesService.getScriptProperties();
  const propsToSet = {};

  data.forEach(([key, value]) => {
    if (key && value !== "") {
      propsToSet[key] = value;
    }
  });

  scriptProps.setProperties(propsToSet, true); // overwrite = true

  Logger.log(`Imported ${Object.keys(propsToSet).length} script properties.`);
}

/***** === ROUTES === *****/

/**
 * Main entry point for the Web App.
 * Handles URL parameters, authentication, and page routing.
 */
function doGet(e) {

  // --- 1. INITIALISATION & PARSING DES PARAMÈTRES ---
  const params = e && e.parameter ? e.parameter : {};

  // ================================================================
  // ⚠️  DEV MODE — MUST BE SET TO false BEFORE PRODUCTION DEPLOY ⚠️
  // In DEV_MODE a fake session is written to CacheService on every
  // page load. This bypasses all authentication checks intentionally.
  // ================================================================
  const DEV_MODE = true;

  const page      = (params.page || (DEV_MODE ? "project-dashboard" : "login")).toLowerCase();
  const viewType  = (params.view || 'desktop').toLowerCase();
  //const viewType  = (params.view || 'mobile').toLowerCase();
  const token     = params.session || (DEV_MODE ? "TEST_TOKEN_12345" : "");
  const resetToken = params.token || "";

  // Mutable route variables
  let user             = null;
  let projectId        = params.projectId || "";
  let transferId       = params.transferId || "";
  let projectName      = "";
  let projectStatus    = "";
  let canEdit          = false;
  let isAuthorized     = false;
  let isClient         = true;
  let isClientViewActive = params.isClientViewActive === 'true';
  let currentView = params.currentView || "";

  const companyName = PropertiesService.getScriptProperties().getProperty('COMPANY_NAME') || "Ehden Vision";

  // --- 2. AUTHENTICATION & ENVIRONMENT HANDLING ---
  if (DEV_MODE) {
    // === MODE DÉVELOPPEMENT ===
    // Hardcoded user — edit as needed for local testing
    user = {
      email: "michel.s.dahdah@gmail.com",
      name:  "Michel Dahdah",
      role:  "admin"
    };

    // Write fake session so downstream getSession_() calls succeed
    CacheService.getScriptCache().put("SESSION_" + token, JSON.stringify(user), 3600);

    // Dev defaults — override via URL if needed (?projectId=XXX)
    //projectId     = projectId || "2602-0001";
    projectId     = "2602-0001";
    projectStatus = "active";
    canEdit       = true;
    isAuthorized  = true;
    isClient      = false;

    // In dev mode, fetch the real project name from the DB if a projectId is set,
    // otherwise fall back to a readable default so the UI doesn't show a blank title.
    if (projectId) {
      try {
        const projectRow = getProjectById_(projectId);
        projectName = projectRow ? projectRow.name : "LES GRAVIERS";
      } catch (_) {
        projectName = "LES GRAVIERS";
      }
    }

  } else {
    // === MODE PRODUCTION ===
    user = getSession_(token) || null;

    if (user) {
      const userRole = (user.role || "").toLowerCase();
      const authorizedRoles      = ['admin', 'directeur', 'collaborateur'];
      const clientExcludedRoles  = ['admin', 'directeur', 'collaborateur', 'viseur'];

      isAuthorized = authorizedRoles.includes(userRole);
      isClient     = !clientExcludedRoles.includes(userRole);

      if (projectId) {
        try {
          const projectRow = getProjectById_(projectId);
          if (projectRow) {
            projectName   = projectRow.name;
            projectStatus = (projectRow.status || "").toLowerCase();
            canEdit       = isAuthorized && (projectStatus === 'active');
          }
        } catch (err) {
          console.error("Erreur récupération projet doGet: " + err.message);
        }
      }
    }
  }

  // --- 3. VÉRIFICATION DES PAGES PUBLIQUES ---
  const publicPages = ['login', 'supportlogin', 'reset-request', 'reset'];

  if (!publicPages.includes(page) && !user) {
    return render_("Login", {
      baseUrl:     ScriptApp.getService().getUrl(),
      companyName: companyName,
      message:     "Session expirée ou invalide.",
      token:       "",
      page:        "login"
    });
  }

  // --- 4. PRÉPARATION DU CONTENEUR APP_DATA ---
  const data = {
    baseUrl:            ScriptApp.getService().getUrl(),
    companyName:        companyName,
    page:               page,
    token:              token,
    view:               viewType,
    currentView:        currentView,
    projectId:          projectId,
    transferId:         transferId,
    projectName:        projectName,
    projectStatus:      projectStatus,
    user:               user,
    isAuthorized:       isAuthorized,
    isClient:           isClient,
    canEdit:            canEdit,
    isClientViewActive: isClientViewActive
  };

  // --- 5. ROUTAGE ET RENDU DES PAGES ---
  switch (page) {
    case "login":
      return render_("Login", data);

    case "reset-request":
      return render_("ResetRequest", data);

    case "reset":
      if (!resetToken) {
        data.message = "Lien de réinitialisation manquant.";
        return render_("Login", data);
      }
      data.resetToken = resetToken;
      return render_("Reset", data);

    case "project-portfolio":
      data.title = "Portfolio";
      return render_("ProjectPortfolio", data);

    case "project-dashboard":
      data.title = "Tableau de Bord";
      return (viewType === 'mobile')
        ? render_("ProjectDashboardMobile", data)
        : render_("ProjectDashboard", data);

    case "locataires":
      data.title = "Locataires";
      return (viewType === 'mobile')
        ? render_("LocatairesMobile", data)
        : render_("Locataires", data);

    case "planning":
      data.title = "Planning";
      return (viewType === 'mobile')
        ? render_("Planning_Mobile", data)
        : render_("Planning", data);

    case "edl":
      data.title = "EDL";
      return (viewType === 'mobile')
        ? render_("EDLMobile", data)
        : render_("EDL", data);

    case "rapport":
      data.title = "Rapport";
      return (viewType === 'mobile')
        ? render_("RapportMobile", data)
        : render_("Rapport", data);

    case "settings":
      data.title = "Settings";
      return (viewType === 'mobile')
        ? render_("SettingsMobile", data)
        : render_("Settings", data);

    case "supportlogin":
      data.title = "Support Login";
      return render_("SupportLogin", data);

    case "support":
      data.title = "Support";
      data.returnTo = params.returnTo || 'login';
      return render_("Support", data);

    default:
      return user ? render_("ProjectPortfolio", data) : render_("Login", data);
  }
}

/**
 * =================================================================
 * 1. CONFIGURATION & CONSTANTS
 * =================================================================
 */
const START_ROW = 5;
const STATUS_ACTIVE = 'Actif';
const STATUS_BLOCKED = 'Bloqué';

function getCompanyName_() {
  return getProp_('COMPANY_NAME') || "Ehden Vision";
}

// Column mapping for the Users Sheet
const COL = {
  NAME: 2,       // Column B
  ENTERPRISE: 3, // Column C
  EMAIL: 4,      // Column D
  PASSWORD: 5,   // Column E
  ROLE: 6,       // Column F
  TEAM: 7,       // Column G
  STATUS: 8      // Column H
};

// Cache & Token Lifespan (in seconds)
const SESSION_TTL = 6 * 60 * 60;   // 6 hours
const RESET_TOKEN_TTL = 3600;      // 1 hour

// Prefix keys for CacheService
const SESSION_CACHE_PREFIX = "SESSION_";
const RESET_CACHE_PREFIX = "RESET_TOKEN_";
const HASH_PREFIX = "HASHv1";

/**
 * =================================================================
 * 2. TEMPLATE RENDERING ENGINE
 * =================================================================
 */

/**
 * Renders an HTML file with the provided data object.
 */
function render_(file, data) {
  const t = HtmlService.createTemplateFromFile(file);
  t.data = data || {};
  return t.evaluate()
    .setTitle(getCompanyName_())
    .addMetaTag("viewport", "width=device-width, initial-scale=1")
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/**
 * Includes a sub-template into a main template (used for CSS/JS separation).
 */
function include_(f, data) {
  const t = HtmlService.createTemplateFromFile(f);
  t.data = data || {};
  return t.evaluate().getContent();
}

/**
 * Returns the current Web App deployment URL.
 */
function getScriptUrl() {
  return ScriptApp.getService().getUrl();
}

/**
 * =================================================================
 * 3. PROPERTIES & SHEET ACCESS
 * =================================================================
 */

/**
 * Helper to fetch Script Properties.
 */
function getProp_(key) {
  return PropertiesService.getScriptProperties().getProperty(key) || "";
}

/**
 * Opens the Spreadsheet and finds the Users sheet.
 */
function getUsersSheet_() {
  const props = PropertiesService.getScriptProperties();
  const ss = SpreadsheetApp.openById(props.getProperty("PERMISSIONS_SPREADSHEET_ID"));
  const sheet = ss.getSheetByName('Utilisateurs');
  if (!sheet) {
    throw new Error("Sheet 'Utilisateurs' not found in the spreadsheet.");
  }
  return sheet;
}

/**
 * Searches for a user row based on their email.
 */
function findUserByEmail_(email) {
  if (!email) return null;

  const sh = getUsersSheet_();
  const last = sh.getLastRow();
  if (last < START_ROW) return null;

  const values = sh.getRange(START_ROW, 1, last - START_ROW + 1, sh.getLastColumn()).getValues();

  for (let i = 0; i < values.length; i++) {
    const row = values[i];
    const rowEmail = String(row[COL.EMAIL - 1]).trim().toLowerCase();
    if (rowEmail === email.toLowerCase()) {
      return {
        rowIndex: START_ROW + i,
        name: row[COL.NAME - 1],
        enterprise: row[COL.ENTERPRISE - 1],
        email: rowEmail,
        passwordCell: row[COL.PASSWORD - 1],
        role: row[COL.ROLE - 1],
        team: row[COL.TEAM - 1],
        status: row[COL.STATUS - 1]
      };
    }
  }
  return null;
}

/**
 * =================================================================
 * 4. SECURITY & PASSWORD HASHING
 * =================================================================
 */

/**
 * Generates a SHA-256 salted hash for a plain text password.
 */
function hashPassword_(plain, saltBytes) {
  let salt = saltBytes;
  if (!salt) {
    salt = [];
    for (let i = 0; i < 16; i++) {
      salt.push(Math.floor(Math.random() * 256) - 128);
    }
  }

  const plainBytes = Utilities.newBlob(plain).getBytes();
  const combined = salt.concat(plainBytes);
  const digest = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, combined);

  return HASH_PREFIX + ":" + toHex_(salt) + ":" + toHex_(digest);
}

/**
 * Converts byte array to Hexadecimal string.
 */
function toHex_(bytes) {
  return bytes.reduce((str, byte) => {
    return str + ("0" + (byte & 0xFF).toString(16)).slice(-2);
  }, "");
}

/**
 * Converts Hexadecimal string back to byte array.
 */
function fromHex_(hex) {
  const bytes = [];
  for (let i = 0; i < hex.length; i += 2) {
    let byte = parseInt(hex.substr(i, 2), 16);
    if (byte > 127) byte -= 256;
    bytes.push(byte);
  }
  return bytes;
}

/**
 * Compares a plain password against a stored hash.
 */
function checkPassword_(plain, hashedFull) {
  if (!hashedFull || !hashedFull.includes(":")) return false;
  const parts = hashedFull.split(":");
  if (parts.length !== 3) return false;

  const saltHex = parts[1];
  const saltBytes = fromHex_(saltHex);
  const attemptHashFull = hashPassword_(plain, saltBytes);
  const attemptHashHex = attemptHashFull.split(":")[2];
  const storedHashHex = parts[2];

  return attemptHashHex === storedHashHex;
}

/**
 * =================================================================
 * 5. SESSION MANAGEMENT
 * =================================================================
 *
 * NOTE: getSession_() is defined in Security_gs — do NOT redefine it here.
 */

/**
 * Génère un jeton unique et stocke le profil utilisateur nettoyé dans CacheService.
 * Stores only identity/display data — never passwords or raw permissions.
 * Role enforcement always happens server-side via getSession_() + assertCanEdit_().
 */
function createSession_(u) {
  const token = Utilities.getUuid();

  const sessionData = {
    email: u.email,
    role: u.role,
    name: u.name,
    enterprise: u.enterprise,
    team: u.team
  };

  CacheService.getScriptCache().put(
    SESSION_CACHE_PREFIX + token,
    JSON.stringify(sessionData),
    SESSION_TTL
  );
  return token;
}

/**
 * =================================================================
 * 6. AUTHENTICATION & PASSWORD ACTIONS
 * =================================================================
 */

/**
 * Validates credentials and returns a session token.
 */
function gsLoginWithEmailPassword(email, password) {
  const u = findUserByEmail_(email);

  if (!u || !checkPassword_(password, u.passwordCell)) {
    throw new Error("Email ou mot de passe incorrect.");
  }

  if (u.status !== STATUS_ACTIVE) {
    throw new Error("Votre compte est suspendu. Contactez le support.");
  }

  return {
    sessionToken: createSession_(u)
  };
}

/**
 * Generates a reset token and sends a link via email.
 */
function gsRequestPasswordReset(email) {
  const u = findUserByEmail_(email);
  // Security best practice: don't reveal if email doesn't exist
  if (!u) return { ok: true };

  const token = Utilities.getUuid();
  CacheService.getScriptCache().put(
    RESET_CACHE_PREFIX + token,
    JSON.stringify({ email: u.email, rowIndex: u.rowIndex }),
    RESET_TOKEN_TTL
  );

  const base = getScriptUrl();
  const link = base + "?page=reset&token=" + encodeURIComponent(token);
  const companyName = getCompanyName_();

  MailApp.sendEmail({
    to: u.email,
    subject: "Réinitialisation du mot de passe - " + companyName,
    htmlBody:
      '<div style="font-family: sans-serif; line-height: 1.6; color: #1e293b; max-width: 600px; margin: auto; border: 1px solid #e2e8f0; padding: 20px; border-radius: 12px;">' +
      '<div style="text-align: center; margin-bottom: 20px;">' +
      '<h2 style="color: #0d59f2; margin: 0;">' + companyName + '</h2>' +
      "</div>" +
      "<p>Bonjour <strong>" + u.name + "</strong>,</p>" +
      "<p>Vous avez demandé la réinitialisation de votre mot de passe pour votre espace projet.</p>" +
      '<div style="text-align: center; margin: 30px 0;">' +
      '<a href="' + link + '" style="background-color: #0d59f2; color: white; padding: 12px 24px; text-decoration: none; border-radius: 8px; font-weight: bold; display: inline-block;">Réinitialiser mon mot de passe</a>' +
      "</div>" +
      '<p style="font-size: 14px; color: #64748b;">Ce lien est valable pendant 1 heure.</p>' +
      '<hr style="border: none; border-top: 1px solid #e2e8f0; margin: 20px 0;">' +
      '<div style="background-color: #f8fafc; padding: 15px; border-radius: 8px; border-left: 4px solid #0d59f2;">' +
      '<p style="font-size: 12px; color: #475569; margin: 0;"><strong>Astuce technique :</strong> Si vous rencontrez une erreur "Google Drive", faites un clic droit sur le bouton bleu et choisissez "Ouvrir dans une fenêtre de navigation privée".</p>' +
      "</div>" +
      '<p style="font-size: 12px; color: #94a3b8; margin-top: 20px; text-align: center;">Ceci est un message automatique, merci de ne pas y répondre.</p>' +
      "</div>"
  });

  return { ok: true };
}

/**
 * Finalizes the password reset by updating the spreadsheet.
 */
function gsResetPassword(token, newPassword) {
  const cacheKey = RESET_CACHE_PREFIX + token;
  const cache = CacheService.getScriptCache().get(cacheKey);

  if (!cache) {
    throw new Error("Le lien a expiré ou est invalide.");
  }

  const data = JSON.parse(cache);
  const newHashedPassword = hashPassword_(newPassword);

  const props = PropertiesService.getScriptProperties();
  const ss = SpreadsheetApp.openById(props.getProperty("PERMISSIONS_SPREADSHEET_ID"));
  const sheet = ss.getSheetByName('Utilisateurs');

  sheet.getRange(data.rowIndex, COL.PASSWORD).setValue(newHashedPassword);

  // Clear token from cache after successful reset — one-time use
  CacheService.getScriptCache().remove(cacheKey);

  return { ok: true };
}

/**
 * =================================================================
 * SÉCURITÉ & CONTRÔLE D'ACCÈS CENTRALISÉ
 * =================================================================
 */

/**
 * Récupère de manière sécurisée la session depuis le CacheService.
 * @param {string} token - Le jeton de session utilisateur.
 * @returns {Object|null} Les données utilisateur nettoyées ou null si expiré/invalide.
 */
function getSession_(token) {
  if (!token) return null;
  try {
    const rawSession = CacheService.getScriptCache().get(SESSION_CACHE_PREFIX + token);
    if (!rawSession) return null;
    return JSON.parse(rawSession);
  } catch (e) {
    console.error("Erreur technique getSession_ : " + e.message);
    return null;
  }
}

/**
 * LE GARDIEN (GATEKEEPER) : Valide la session, le rôle et le statut du projet.
 * À appeler en PREMIÈRE ligne de chaque fonction de modification (écriture/suppression).
 *
 * @param {string} token     - Le jeton de session transmis par le client.
 * @param {string} projectId - L'ID du projet concerné par la modification.
 * @returns {Object} L'objet utilisateur validé si toutes les conditions sont remplies.
 * @throws {Error} Interrompt immédiatement l'exécution si une règle de sécurité est violée.
 */
function assertCanEdit_(token, projectId) {
  // 1. Authentification
  if (!token) {
    throw new Error("Sécurité : Jeton de session manquant. Action refusée.");
  }
  const user = getSession_(token);
  if (!user) {
    throw new Error("Sécurité : Votre session a expiré. Veuillez recharger la page.");
  }

  // 2. Autorisation par rôle
  const authorizedRoles = ['admin', 'directeur', 'collaborateur'];
  const userRole = (user.role || "").toLowerCase();
  if (!authorizedRoles.includes(userRole)) {
    throw new Error("Sécurité : Vos droits actuels ne vous permettent pas d'effectuer cette modification.");
  }

  // 3. Validation de l'état du projet (contre la falsification d'URL)
  if (projectId) {
    const project = getProjectById_(projectId);
    if (!project) {
      throw new Error("Sécurité : Le projet spécifié est introuvable.");
    }
    if ((project.status || "").toLowerCase() !== "active") {
      throw new Error("Sécurité : Ce projet est verrouillé (Inactif/Bloqué). Toute modification est impossible.");
    }
  }

  return user;
}

/**
 * =================================================================
 * LOGGING — UNIVERSAL & ERROR
 * =================================================================
 *
 * Structure des colonnes :
 *   A=Log_ID, B=Timestamp, C=Entity_ID, D=Visibility,
 *   E=Type, F=User, G=Action, H=Payload
 */

/**
 * Resolves the sheet a given module's entries live in — the ONE place that
 * decides "Logs_<module>", shared by the write side (gsWriteUniversalLog,
 * below) and the read side (gsGetUniversalLog, further down) so they can
 * never drift apart. Any module gets its own sheet (edl, travaux, elec,
 * sanit, reserves, formulaires, locataires, communs, facades, or anything
 * added later) — there is no whitelist to keep updated as the app grows.
 * A blank/missing module is the only case that falls back to "Logs_system".
 */
function _resolveLogSheetName(module) {
  const clean = String(module || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_");
  return clean ? "Logs_" + clean : "Logs_system";
}

/**
 * Writes a structured log entry to the appropriate module sheet.
 *
 * @param {string} token   - Session token (required — validates the caller).
 * @param {Object} payload - Log payload object.
 */
function gsWriteUniversalLog(token, payload) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");

  try {
    const props = PropertiesService.getScriptProperties();
    const ssId = props.getProperty("LOG_SPREADSHEET_ID");

    if (!ssId) {
      throw new Error("LOG_SPREADSHEET_ID property is missing.");
    }

    const ss = SpreadsheetApp.openById(ssId);

    // Route to the module's own sheet — same resolver the read side uses.
    const sheetName = _resolveLogSheetName(payload.module);

    let sheet = ss.getSheetByName(sheetName);

    // Auto-create the sheet with headers if it doesn't exist yet
    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
      sheet.appendRow(["Log_ID", "Timestamp", "Entity_ID", "Visibility", "Type", "User", "Action", "Payload"]);
      sheet.getRange("A1:H1").setFontWeight("bold").setBackground("#e2e8f0");
      sheet.setFrozenRows(1);
    }

    const logId      = Utilities.getUuid();
    const timestamp  = new Date();
    const entityId   = payload.id || "N/A";
    const visibility = payload.visibility || "Private";
    const type       = payload.type || "Detail";
    const logUser    = payload.userEmail || Session.getActiveUser().getEmail() || "Inconnu";
    const logAction  = payload.action || "SANS_ACTION";

    let detailsStr = "{}";
    if (payload.details) {
      detailsStr = (typeof payload.details === 'object')
        ? JSON.stringify(payload.details)
        : String(payload.details);
    }

    sheet.appendRow([logId, timestamp, entityId, visibility, type, logUser, logAction, detailsStr]);

  } catch (e) {
    gsWriteErrorLog(
      e.message || e.toString(),
      e.stack    || "Aucune trace disponible",
      "gsWriteUniversalLog",
      payload
    );
  }
}

/**
 * Writes an error entry to the "Errors" sheet.
 *
 * Columns: A(empty), B(Timestamp), C(Email), D(Message),
 *          E(Stack Trace), F(Context), G(Payload)
 *
 * @param {string} errorMessage - The error message string.
 * @param {string} stackTrace   - The stack trace string.
 * @param {string} context      - The function or location where the error occurred.
 * @param {*}      payload      - Any additional data to record (will be JSON-stringified).
 */
function gsWriteErrorLog(errorMessage, stackTrace, context, payload) {
  try {
    const props = PropertiesService.getScriptProperties();
    const ssId = props.getProperty("LOG_SPREADSHEET_ID");

    if (!ssId) {
      console.error("gsWriteErrorLog: LOG_SPREADSHEET_ID property is missing.");
      return;
    }

    const sheet = SpreadsheetApp.openById(ssId).getSheetByName("Errors");
    if (!sheet) {
      console.error("gsWriteErrorLog: Sheet 'Errors' not found in the target spreadsheet.");
      return;
    }

    const timestamp = new Date();
    const userEmail = Session.getActiveUser().getEmail() || "Inconnu";

    let safePayload = "";
    if (payload) {
      try {
        safePayload = typeof payload === 'object' ? JSON.stringify(payload) : String(payload);
      } catch (_) {
        safePayload = "Could not stringify payload";
      }
    }

    sheet.appendRow([
      "",            // Col A: Empty (reserved)
      timestamp,     // Col B: Timestamp
      userEmail,     // Col C: User Email
      errorMessage,  // Col D: Error Message
      stackTrace,    // Col E: Stack Trace
      context,       // Col F: Context / Origin
      safePayload    // Col G: Payload
    ]);

  } catch (loggingError) {
    // Ultimate fallback — if even this fails, at least log to the GAS console
    console.error("gsWriteErrorLog: Critical failure writing to Error sheet: ", loggingError);
  }
}

/**
 * =================================================================
 * UNIVERSAL LOG — READ SIDE (Journal Universel / "Historique")
 * =================================================================
 * Read-side counterpart to gsWriteUniversalLog() above. Generic and
 * cross-module on purpose — this is THE global extraction function: any
 * page's "Historique" button calls this (via ClientLib.txt's
 * fetchHistory()/showHistoryModal()) for any (module, id) pair — EDL,
 * Travaux, Élec, Sanit, Réserves, Formulaires, Locataires, Communs,
 * Facades, or any future module — without needing to know anything about
 * that module beyond its name and the entity's ID.
 *
 * Moved here from EDL_gs.txt so it lives next to its write-side
 * counterpart instead of being tied to one page's server file — that
 * earlier copy (and its UNIVERSAL_LOG_SS_ID / UNIVERSAL_LOG_SHEET_NAME
 * placeholders) has been removed from EDL_gs.txt to avoid two conflicting
 * definitions in the same Apps Script project.
 *
 * Privacy — two independent layers, deliberately kept separate:
 *   A) isClient (real client accounts): enforced HERE, server-side, before
 *      data ever leaves the server. A Private-visibility entry is skipped
 *      entirely for a client session — never sent, not just hidden in the UI.
 *   B) Private notes/fields *inside* a Public entry's payload (e.g. a
 *      "Notes" group holding both a public and a private note) are stripped
 *      by _stripPrivateDetailsDeep() below, recursively, wherever they sit
 *      in the details tree — a flat/top-level-only check would miss a note
 *      nested inside a group like "Note Privée (Interne)". Convention: any
 *      details key whose name contains "priv" (accent/case-insensitive —
 *      matches privateNote, privNote, "Privée", "Private", ...) is treated
 *      as private. Keep using that naming convention for anything that must
 *      stay internal. Mirrored client-side in ClientLib.txt's
 *      PRIVATE_DETAIL_KEYS (that copy is a presentation-only simulation for
 *      the staff ClientView toggle — see ClientLib.txt section 10 — this
 *      one is the real, enforced boundary).
 *   The staff "ClientView" preview toggle never touches this function:
 *   staff sessions always get the full, unfiltered list from here.
 *
 * C) Type is always extracted per entry ('Milestone' or 'Detail') so any
 *    caller can decide how to display it — e.g. ClientLib.txt's
 *    showHistoryModal() shows Milestone rows by default with an expand
 *    button that reveals Detail rows.
 * D) This function itself never filters by type — Milestone and Detail
 *    entries are always returned together; it's purely a display choice
 *    made by whoever renders the list (see C).
 */

// Keys inside a log entry's `details` object that are never shown to a
// client-type session, even when the entry itself is Public — matched as a
// case/accent-insensitive SUBSTRING against each key name, at any nesting
// depth (see _stripPrivateDetailsDeep below). Mirrored client-side in
// ClientLib.txt's PRIVATE_DETAIL_KEYS — keep both lists in sync.
const PRIVATE_DETAIL_KEYS = ['priv'];

/**
 * Resolves a header's column index by trying a list of candidate labels.
 * Both the header and each candidate are normalized (lowercased, accents
 * and non-alphanumeric characters stripped) before comparing, so "Log_ID",
 * "log id" and "logid" all match the same candidate — column order, casing
 * and separators in the sheet don't matter, only the letters/digits do.
 */
function _findLogCol(headers, candidates) {
  const norm = s => String(s).trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // strip accents
    .replace(/[^a-z0-9]/g, '');                        // strip spaces/underscores/punct
  const normalizedHeaders = headers.map(norm);
  for (const c of candidates) {
    const idx = normalizedHeaders.indexOf(norm(c));
    if (idx !== -1) return idx;
  }
  return -1;
}

/**
 * ⚠️ CONFIRM: adjust if getSession_() names/derives the client flag
 * differently (e.g. user.role === 'client'). Kept as its own one-line
 * function on purpose, so there's exactly one place to fix if it differs.
 * Matches APP_DATA.isClient, which EDL_Script_1.txt reads straight off the
 * same session-derived user object server-side.
 */
function _isClientSession(user) {
  return !!(user && user.isClient === true);
}

/**
 * True if `key`'s normalized name (lowercased, accents stripped) contains
 * one of the PRIVATE_DETAIL_KEYS markers.
 */
function _matchesPrivateKey(key) {
  const k = String(key).trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  return PRIVATE_DETAIL_KEYS.some(marker => k.includes(marker));
}

/**
 * Recursively strips any key — at any nesting depth, inside plain objects
 * and arrays alike — that matches _matchesPrivateKey(). Needed because a
 * private note can sit several levels down (e.g. a "2. Notes Renseignées"
 * group containing both "Note Publique" and "Note Privée (Interne)"); a
 * flat top-level-only check would miss it and leak the private one to a
 * client session. Returns a NEW value — the input is never mutated.
 */
function _stripPrivateDetailsDeep(value) {
  if (Array.isArray(value)) {
    return value.map(_stripPrivateDetailsDeep);
  }
  if (value && typeof value === 'object') {
    const out = {};
    Object.keys(value).forEach(k => {
      if (_matchesPrivateKey(k)) return; // drop this key (and everything under it) entirely
      out[k] = _stripPrivateDetailsDeep(value[k]);
    });
    return out;
  }
  return value; // primitive — nothing to strip
}

/**
 * Returns the history of a single (module, id) pair, most recent first.
 *
 * `projectId` is accepted for consistency with the rest of the app and to
 * leave room for a future project-scoped permission check; it isn't
 * currently used to pick the spreadsheet, since the Journal is a single
 * cross-project log.
 *
 *   gsGetUniversalLog(token, projectId, 'reserves', 'R-2026-004')
 *   gsGetUniversalLog(token, projectId, 'edl', 'LOT-014')
 *
 * Returns: [{ id, module, entityId, action, visibility, type, details,
 *             userEmail, timestamp }, ...]. For a client session, Private
 * entries are omitted entirely (A) and any private field inside `details`
 * is stripped, however deeply nested (B). `type` is always present (C) and
 * is never filtered on here — Milestone and Detail entries both come back
 * together (D); the caller decides how to display each.
 */
function gsGetUniversalLog(token, projectId, module, entityId) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");
  if (!module || !entityId) return [];

  const isClientUser = _isClientSession(user);

  const props = PropertiesService.getScriptProperties();
  const ssId = props.getProperty("LOG_SPREADSHEET_ID");
  if (!ssId) throw new Error("LOG_SPREADSHEET_ID property is missing.");

  const ss = SpreadsheetApp.openById(ssId);
  const sheetName = _resolveLogSheetName(module);
  const sheet = ss.getSheetByName(sheetName);

  // No sheet yet simply means nothing has ever been logged for this module
  // — a normal state for a brand-new module/entity, not an error.
  if (!sheet) return [];

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];

  const data = sheet.getDataRange().getValues();
  const headers = data[3]; // row 4 — header row

  const col = {
    logId:      _findLogCol(headers, ['log_id', 'logid']),
    timestamp:  _findLogCol(headers, ['timestamp', 'date', 'horodatage']),
    entityId:   _findLogCol(headers, ['entity_id', 'entityid']),
    visibility: _findLogCol(headers, ['visibility', 'visibilite', 'visibilité']),
    type:       _findLogCol(headers, ['type']),
    userEmail:  _findLogCol(headers, ['user', 'useremail', 'user email', 'email', 'utilisateur']),
    action:     _findLogCol(headers, ['action']),
    payload:    _findLogCol(headers, ['payload', 'details', 'détails'])
  };

  if (col.entityId === -1) {
    throw new Error(`Colonne Entity_ID introuvable dans la feuille "${sheetName}".`);
  }

  const targetId = String(entityId).trim();
  const results = [];

  for (let i = 4; i < data.length; i++) {
    const row = data[i];
    if (String(row[col.entityId]).trim() !== targetId) continue;

    const visibility = col.visibility !== -1 ? String(row[col.visibility]).trim() : 'Public';
    if (isClientUser && visibility === 'Private') continue; // A — fully-private entry: skip entirely

    let details = {};
    if (col.payload !== -1) {
      const raw = row[col.payload];
      try {
        details = raw ? JSON.parse(raw) : {};
      } catch (e) {
        details = { raw: String(raw) }; // legacy/non-JSON cell — surface it rather than losing it silently
      }
    }
    if (isClientUser) {
      details = _stripPrivateDetailsDeep(details); // B — private notes/fields, however deeply nested
    }

    const rawTs = col.timestamp !== -1 ? row[col.timestamp] : null;
    const timestamp = (rawTs instanceof Date) ? rawTs.toISOString() : String(rawTs || '');

    results.push({
      id:         col.logId !== -1 ? String(row[col.logId]) : `${sheetName}-${i + 1}`,
      module:     String(module).trim(),
      entityId:   targetId,
      action:     col.action !== -1 ? String(row[col.action]).trim() : '',
      visibility: visibility,
      type:       (col.type !== -1 && String(row[col.type]).trim()) || 'Milestone', // C — always extracted
      details:    details,
      userEmail:  col.userEmail !== -1 ? String(row[col.userEmail]).trim() : '',
      timestamp:  timestamp
    });
    // D — no type filtering: Milestone and Detail entries both included above.
  }

  results.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp)); // most recent first
  return results;
}

/**
 * =================================================================
 * 1. PROJECT SHEET CONFIGURATION
 * =================================================================
 */
const PROJECT_START_ROW = 5;

const PROJECT_COL = {
  ID: 2,          // Column B
  NAME: 3,        // Column C
  OWNER: 4,       // Column D
  STATUS: 5,      // Column E (Active/Ended/Blocked/Archived)
  START: 6,       // Column F
  END: 7,         // Column G
  CITY: 8,        // Column H
  COUNTRY: 9,     // Column I
  PROGRESS: 10,   // Column J (%)
  UNITS: 11,      // Column K
  DESC: 12        // Column L
};

/**
 * =================================================================
 * 2. DATA RETRIEVAL & IMAGE OPTIMIZATION
 * =================================================================
 */

/**
 * Fetches the list of projects and maps them to objects.
 * Includes base64 thumbnails for high-performance loading.
 */
function gsListProjects(token) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");

  const props = PropertiesService.getScriptProperties();
  const ss = SpreadsheetApp.openById(props.getProperty("PROJECT_LIST_ID"));
  const sh = ss.getSheetByName('Projects');

  const last = sh.getLastRow();
  if (last < PROJECT_START_ROW) return [];

  const values = sh.getRange(PROJECT_START_ROW, 1, last - PROJECT_START_ROW + 1, PROJECT_COL.DESC).getValues();
  const tz = Session.getScriptTimeZone() || "Europe/Paris";

  // Load Project Photos from Drive
  const logoFolderId = getProp_("PROJECT_PHOTOS_FILE");
  const logoMap = {};

  if (logoFolderId) {
    try {
      const folder = DriveApp.getFolderById(logoFolderId);
      const files = folder.getFiles();
      while (files.hasNext()) {
        const file = files.next();
        const nameWithoutExt = file.getName().split('.')[0].toLowerCase();
        // PERFORMANCE: Fetch the thumbnail blob instead of the full file
        const thumb = file.getThumbnail();
        const b64 = Utilities.base64Encode(thumb.getBytes());
        logoMap[nameWithoutExt] = "data:image/png;base64," + b64;
      }
    } catch (e) {
      console.error("Error accessing projects photos folder: " + e.toString());
    }
  }

  const projects = [];
  const defaultImg = defaultProjectImage_();

  for (let i = 0; i < values.length; i++) {
    const row = values[i];
    const id   = String(row[PROJECT_COL.ID   - 1] || "").trim();
    const name = String(row[PROJECT_COL.NAME - 1] || "").trim();

    if (!id && !name) continue;

    const finalImage = logoMap[id.toLowerCase()] || defaultImg;

    projects.push({
      id,
      name,
      owner: String(row[PROJECT_COL.OWNER - 1] || "").trim(),
      status: String(row[PROJECT_COL.STATUS - 1] || "").trim(),
      startDate: isValidDate_(row[PROJECT_COL.START - 1])
        ? Utilities.formatDate(row[PROJECT_COL.START - 1], tz, "dd/MM/yyyy") : "",
      endDate: isValidDate_(row[PROJECT_COL.END - 1])
        ? Utilities.formatDate(row[PROJECT_COL.END - 1], tz, "dd/MM/yyyy") : "",
      city:    String(row[PROJECT_COL.CITY    - 1] || "").trim(),
      country: String(row[PROJECT_COL.COUNTRY - 1] || "").trim(),
      // Handle percentage conversion (0.1 → 10%)
      progress: Math.max(0, Math.min(100, Math.round(100 * Number(row[PROJECT_COL.PROGRESS - 1] || 0)))),
      units:       String(row[PROJECT_COL.UNITS - 1] || "").trim(),
      description: String(row[PROJECT_COL.DESC  - 1] || "").trim(),
      image: finalImage
    });
  }

  // Alphabetical sort by project name
  projects.sort((a, b) => (a.name || "").localeCompare(b.name || "", "fr", { sensitivity: "base" }));
  return projects;
}

/**
 * =================================================================
 * 3. UTILITIES
 * =================================================================
 */

/**
 * Fetches a single project row by ID for server-side permission checks.
 * Used by ROUTES and assertCanEdit_ to verify project status without
 * trusting the client-supplied URL parameter.
 *
 * @param {string} projectId
 * @returns {{ id: string, status: string, name: string } | null}
 */
function getProjectById_(projectId) {
  if (!projectId) return null;
  try {
    const props = PropertiesService.getScriptProperties();
    const ss = SpreadsheetApp.openById(props.getProperty("PROJECT_LIST_ID"));
    const sh = ss.getSheetByName('Projects');
    const last = sh.getLastRow();
    if (last < PROJECT_START_ROW) return null;

    // ID at col 2, NAME at col 3, STATUS at col 5.
    // We read from col 1 to PROJECT_COL.STATUS to get all needed columns in one shot.
    const numRows = last - PROJECT_START_ROW + 1;
    const rows = sh.getRange(PROJECT_START_ROW, 1, numRows, PROJECT_COL.STATUS).getValues();

    const target = String(projectId).trim().toLowerCase();

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const rowId = String(row[PROJECT_COL.ID - 1]).trim();
      if (rowId.toLowerCase() === target) {
        return {
          id:     rowId,
          name:   String(row[PROJECT_COL.NAME   - 1]).trim(),
          status: String(row[PROJECT_COL.STATUS  - 1]).trim()
        };
      }
    }
    return null;

  } catch (e) {
    console.error("getProjectById_: " + e.message);
    return null;
  }
}

/**
 * Validates a Date object.
 */
function isValidDate_(d) {
  return d instanceof Date && !isNaN(d.getTime());
}

/**
 * Generates a clean placeholder SVG as a Base64 data URL.
 */
function defaultProjectImage_() {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="600" viewBox="0 0 1200 600">
    <rect width="100%" height="100%" fill="#f1f5f9"/>
    <text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" font-family="sans-serif" font-size="24" fill="#94a3b8">Image non disponible</text>
  </svg>`;
  const b64 = Utilities.base64Encode(svg, Utilities.Charset.UTF_8);
  return "data:image/svg+xml;base64," + b64;
}

/**
 * ==========================================
 * 1. DATA FETCHING LOGIC
 * ==========================================
 */

/**
 * Main entry point: Fetches locataires, communs, facades, and planning data.
 * @param {string} token     - Session token from the client.
 * @param {string} projectId - Passed through for context/logging but not used for auth.
 */
function getLocatairesPageData(token, projectId) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");

  return {
    locataires:     fetchSheetData('Locataires'),
    communs:        fetchSheetData('Parties communes'),
    facades:        fetchSheetData('Facades'),
    configFacades:  fetchSheetData('Config Facades'),
    planning:       fetchAllNotes()
  };
}

/**
 * Reads planning notes from all three Planning sheets and merges them
 * into a single map keyed by unit/lot ID.
 */
function fetchAllNotes() {
  try {
    // PLANNING_SS_ID is declared as a file-scope constant in Planning_gs
    if (!PLANNING_SS_ID) return {};

    const ss = SpreadsheetApp.openById(PLANNING_SS_ID);
    const notesSheets = ['Planning', 'Planning Communs', 'Planning Facades'];
    const combinedNotes = {};

    notesSheets.forEach(sheetName => {
      const sheet = ss.getSheetByName(sheetName);
      if (sheet && sheet.getLastRow() >= 7) {
        const data = sheet.getRange(7, 1, sheet.getLastRow() - 6, 3).getValues();

        data.forEach(row => {
          const id = String(row[0] || '').trim();
          if (!id) return;

          const status  = String(row[1] || '').trim();
          const rawNote = String(row[2] || '').trim();

          let pubNote  = "";
          let privNote = "";

          if (rawNote.startsWith('{') && rawNote.endsWith('}')) {
            try {
              const parsed = JSON.parse(rawNote);
              pubNote  = parsed.pub  || "";
              privNote = parsed.priv || parsed.int || "";
            } catch (_) {
              pubNote = rawNote;
            }
          } else {
            pubNote = rawNote;
          }

          combinedNotes[id] = { status, note: pubNote, privateNote: privNote };
        });
      }
    });

    return combinedNotes;
  } catch (e) {
    console.error("Erreur fetchAllNotes:", e);
    return {};
  }
}

/**
 * Generic sheet reader — reads all data rows starting from row 7, column B.
 * @param {string} sheetName - 'Locataires', 'Parties communes', or 'Facades'
 */
function fetchSheetData(sheetName) {
  // BATIMENTS_SS_ID is declared as a file-scope constant in Planning_gs
  const ss    = SpreadsheetApp.openById(BATIMENTS_SS_ID);
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) throw new Error("Feuille introuvable : " + sheetName);

  const startRow = 7;
  const startCol = 2; // Column B

  const lastRow = sheet.getLastRow();
  if (lastRow < startRow) return [];

  let numCols;
  if (sheetName === 'Locataires')       numCols = 20;
  else if (sheetName === 'Parties communes') numCols = 8;
  else if (sheetName === 'Facades')     numCols = 8;
  else                                  numCols = sheet.getLastColumn() - 1;

  const values = sheet.getRange(startRow, startCol, lastRow - startRow + 1, numCols).getValues();

  // Remove empty rows (Column B empty)
  const cleaned = values.filter(r => r[0] !== "" && r[0] !== null && r[0] !== undefined);

  return cleaned.map(row => {

    if (sheetName === 'Locataires') {
      return {
        id:               row[0],
        batiment:         row[2],
        hall:             row[3],
        etage:            row[4],
        empilement:       row[5],
        porte:            row[6],
        typeLog:          row[7],
        configLogement:   row[8],
        surface:          row[9],
        nom:              String(row[10]).toUpperCase(),
        prenom:           formatProperCase(String(row[11])),
        adresse:          row[12],
        ville:            row[13],
        telFixe:          formatPhoneForUi(row[14]),
        telPort1:         formatPhoneForUi(row[15]),
        telPort2:         formatPhoneForUi(row[16]),
        email:            row[17],
        email2:           row[18],
        reference:        row[19]
      };
    }

    if (sheetName === 'Parties communes') {
      return {
        id:          row[0],
        batiment:    row[2],
        hall:        row[3],
        etage:       row[4],
        description: row[5],
        ref:         row[6],
        abr:         row[7]
      };
    }

    if (sheetName === 'Facades') {
      return {
        id:          String(row[0] || '').trim(),
        id2:         String(row[1] || '').trim(),
        batiment:    String(row[2] || '').trim(),
        hall:        String(row[3] || '').trim(),
        orientation: String(row[4] || '').trim(),
        trame:       String(row[5] || '').trim(),
        partie:      String(row[6] || '').trim(),
        type:        String(row[7] || '').trim()
      };
    }

    if (sheetName === 'Config Facades') {
      return {
        type:        String(row[0] || '').trim(), // Column B
        description: String(row[1] || '').trim()  // Column C
      };
    }

    return { id: row[0] };
  });
}


/**
 * ==========================================
 * 2. DATA UPDATE OPERATIONS
 * ==========================================
 */

/**
 * Updates a Locataire contact row and its corresponding Planning entry.
 *
 * Security: assertCanEdit_(token, projectId) validates:
 *   1. Session token is valid
 *   2. User role is authorized (admin / directeur / collaborateur)
 *   3. Project status is 'Active' (fetched from DB — not trusted from client)
 */
function updateLocataireData(token, projectId, payload) {
  const user = assertCanEdit_(token, projectId);
  // assertCanEdit_ throws on failure, so reaching here means the user is authorized.

  // BATIMENTS_SS_ID is declared as a file-scope constant in Planning_gs
  const ss    = SpreadsheetApp.openById(BATIMENTS_SS_ID);
  const sheet = ss.getSheetByName('Locataires');

  // Find the row by ID in Column B
  const data     = sheet.getRange(7, 2, sheet.getLastRow() - 6, 1).getValues();
  const rowIndex = data.findIndex(row => String(row[0]) === String(payload.id));

  if (rowIndex === -1) throw new Error("Identifiant non trouvé.");

  const sheetRow   = rowIndex + 7;
  const cleanPhone = (num) => String(num).replace(/\s/g, '');

  // Write contact fields
  sheet.getRange(sheetRow, 12, 1, 2).setValues([[
    payload.nom.toUpperCase(),
    formatProperCase(payload.prenom)
  ]]);
  sheet.getRange(sheetRow, 16, 1, 5).setValues([[
    cleanPhone(payload.telFixe),
    cleanPhone(payload.telPort1),
    cleanPhone(payload.telPort2),
    payload.email,
    payload.email2
  ]]);

  updatePlanningData(payload);
  return true;
}

/**
 * Updates only the planning entry (status, notes) for Communs and Facades.
 * Maps the target sheet explicitly based on the front-end active view context.
 */
function updatePlanningOnlyData(token, projectId, view, payload) {
  const user = assertCanEdit_(token, projectId);

  // Map the view explicitly to the correct spreadsheet sheet tab
  const sheetName = view === 'communs' ? 'Planning Communs'
                  : view === 'facades' ? 'Planning Facades'
                  : 'Planning';

  updatePlanningData(payload, sheetName);
  return true;
}

/**
 * Writes or updates a row in the appropriate Planning sheet.
 * Enhanced to accept an explicit sheet name to override automatic ID prefix checking.
 */
function updatePlanningData(payload, explicitSheetName) {
  if (!PLANNING_SS_ID) return;

  const ss = SpreadsheetApp.openById(PLANNING_SS_ID);

  const id = String(payload.id || '');

  // Use the explicit sheet name if provided, otherwise fall back to ID parsing
  const sheetName = explicitSheetName || (
                    id.startsWith('COM-') ? 'Planning Communs'
                  : id.startsWith('FAC-') ? 'Planning Facades'
                  : 'Planning'
  );

  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return;

  const startRow   = 7;
  const COL_ID     = 1;
  const COL_STATUS = 2;
  const COL_NOTES  = 3;

  const lastRow = sheet.getLastRow();
  let data = [];
  if (lastRow >= startRow) {
    data = sheet.getRange(startRow, COL_ID, lastRow - startRow + 1, 1).getValues();
  }

  const rowIndex = data.findIndex(row => String(row[0]).trim() === id.trim());

  const notesObj = {
    pub:  payload.planNote        || "",
    priv: payload.planPrivateNote || ""
  };
  const notesString = (notesObj.pub === "" && notesObj.priv === "")
    ? ""
    : JSON.stringify(notesObj);

  if (rowIndex === -1) {
    const newRowIndex = Math.max(lastRow + 1, startRow);
    sheet.getRange(newRowIndex, COL_ID, 1, 3).setValues([[
      payload.id,
      payload.planStatus || "",
      notesString
    ]]);
  } else {
    const sheetRow = startRow + rowIndex;
    sheet.getRange(sheetRow, COL_STATUS, 1, 2).setValues([[
      payload.planStatus || "",
      notesString
    ]]);
  }
}




/**
 * ==========================================
 * 3. FORMATTING UTILITIES
 * ==========================================
 */

/**
 * Converts "JEAN-PIERRE" or "jean pierre" to "Jean-Pierre".
 */
function formatProperCase(str) {
  return str.toLowerCase().replace(/(^|\s|-)\S/g, L => L.toUpperCase());
}

/**
 * Formats a raw phone number for UI display: "0X XX XX XX XX"
 */
function formatPhoneForUi(num) {
  if (!num) return "";
  let s = String(num).replace(/\s/g, '');

  // Correct missing leading zero for 9-digit numbers
  if (s.length === 9 && !s.startsWith('0')) s = '0' + s;

  return s.replace(/(\d{2})(?=\d)/g, '$1 ').trim();
}

// =========================================================
// 0. FILE-SCOPE CONSTANTS — cached once, reused by every function
// =========================================================
// PropertiesService.getScriptProperties() was previously called 32 times (once per function).
// Caching here eliminates the repeated overhead.
const _SCRIPT_PROPS     = PropertiesService.getScriptProperties();
const PLANNING_SS_ID    = _SCRIPT_PROPS.getProperty('PLANNING_SPREADSHEET_ID');
const RESERVES_SS_ID    = _SCRIPT_PROPS.getProperty('RESERVES_SPREADSHEET_ID');
const BATIMENTS_SS_ID   = _SCRIPT_PROPS.getProperty('BATIMENTS_SPREADSHEET_ID');
const EDL_SS_ID         = _SCRIPT_PROPS.getProperty('EDL_SPREADSHEET_ID');

// =========================================================
// 1. Extraction optimisée du planning pour une fenêtre horizontale (dates) et verticale (bâtiment)
// =========================================================
function getSheetNames(view) {
  const map = {
    'locataires': { plan: 'Planning', source: 'Locataires', recap: 'Recap', avancement: 'avancement', planReserves: 'Planning Reserves' , reserves: 'Reserves' , autocontroles: 'AutoControle' , notes: 'Notes'},
    'communs': { plan: 'Planning Communs', source: 'Parties communes', recap: 'Recap Communs', avancement: 'avancement Communs', planReserves: 'Planning Reserves Communs' , reserves: 'Reserves Communs' , autocontroles: 'AutoControle Communs' , notes: 'Notes Communs'},
    'facades': { plan: 'Planning Facades', source: 'Facades', recap: 'Recap Facades', avancement: 'Avancement Facades', planReserves: 'Planning Reserves Facades' , reserves: 'Reserves Facades' , autocontroles: 'AutoControle Facades' , notes: 'Notes Facades'}
  };
  return map[view] || map['locataires'];
}

function gsGetPlanningWindow(token, projectId, startDateStr, endDateStr, currentView, batimentFilter, isClient) {

  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");

  const names = getSheetNames(currentView);
  const ssPlanning = SpreadsheetApp.openById(PLANNING_SS_ID);
  const shPlan = ssPlanning.getSheetByName(names.plan);
  const shPlanReserves = ssPlanning.getSheetByName(names.planReserves);

  const ssSource = SpreadsheetApp.openById(BATIMENTS_SS_ID);
  const shSource = ssSource.getSheetByName(names.source);

  const startDate = new Date(startDateStr);
  const endDate = new Date(endDateStr);
  startDate.setHours(0,0,0,0);
  endDate.setHours(23,59,59,999);

  const lastCol = shPlan.getLastColumn();
  if (lastCol < 8) return emptyResult(startDateStr, endDateStr);
  const dateRow2 = shPlan.getRange(2, 8, 1, lastCol - 7).getValues()[0];

  let colStart = null, colEnd = null;
  for (let i = 0; i < dateRow2.length; i++) {
    const d = dateRow2[i];
    if (!(d instanceof Date)) continue;
    if (colStart === null && d >= startDate) colStart = i;
    if (d <= endDate) colEnd = i;
  }

  if (colStart === null || colEnd === null) return emptyResult(startDateStr, endDateStr);
  const colStartAbs = 8 + colStart;
  const colEndAbs   = 8 + colEnd;
  const windowSize  = colEndAbs - colStartAbs + 1;

  // FIX 4: Read all 6 header rows in one batched getRange call instead of 5 separate calls.
  // Rows: 1=workingDays, 2=dates(already read), 3=months, 4=weeks, 5=weekdays, 6=quant
  const headerBlock = shPlan.getRange(1, colStartAbs, 6, windowSize).getDisplayValues();
  const headers = {
    workingDays: headerBlock[0],
    months:      headerBlock[2],
    weeks:       headerBlock[3],
    weekdays:    headerBlock[4],
    quant:       headerBlock[5],
    dates: dateRow2.slice(colStart, colEnd + 1).map(d => {
      if (d instanceof Date) return Utilities.formatDate(d, ssPlanning.getSpreadsheetTimeZone(), "yyyy-MM-dd");
      return String(d);
    })
  };

  // 1. MÉTADONNÉES LOGEMENTS
  const logementsMeta = _buildLogementsMeta(shSource, currentView, batimentFilter);

  // --- FONCTION UTILITAIRE POUR EXTRAIRE AVANCEMENT ET NOTES ---
  function extractTaskData(sheetName) {
    const dataMap = {};
    const sheet = ssPlanning.getSheetByName(sheetName);
    if (!sheet) return dataMap;
    const lastRow = sheet.getLastRow();
    const lastCol = sheet.getLastColumn();
    if (lastRow >= 7 && lastCol >= 2) {
      const hdrs = sheet.getRange(6, 2, 1, lastCol - 1).getValues()[0];
      const grid = sheet.getRange(7, 1, lastRow - 6, lastCol).getValues();
      for (let r = 0; r < grid.length; r++) {
        const id = String(grid[r][0]).trim();
        if (!id || !logementsMeta[id]) continue;
        for (let c = 1; c < grid[r].length; c++) {
          const cellVal = String(grid[r][c]).trim();
          if (cellVal !== "") {
            if (!dataMap[id]) dataMap[id] = {};
            dataMap[id][hdrs[c - 1]] = cellVal; // Format: dataMap["ID_Logement"]["PLOMB"] = "En cours"
          }
        }
      }
    }
    return dataMap;
  }

  // 2. EXTRACTION DES DONNÉES SÉPARÉES (TÂCHES)
  const notesData = isClient ? {} : extractTaskData(names.notes);
  const avancData = extractTaskData(names.avancement);

  // 3. FUSION AVEC LE PLANNING (DATES)
  const lastRowPlan = shPlan.getLastRow();
  if (lastRowPlan <= 6) return emptyResult(startDateStr, endDateStr);

  const gridMeta  = shPlan.getRange(7, 1, lastRowPlan - 6, 3).getValues();
  const gridSlice = shPlan.getRange(7, colStartAbs, lastRowPlan - 6, windowSize).getValues();
  const planningRows = [];

  for (let r = 0; r < gridMeta.length; r++) {
    const id = gridMeta[r][0];
    if (!id || !logementsMeta[id]) continue;

    for (let c = 0; c < gridSlice[r].length; c++) {
      if (gridSlice[r][c]) {
        let tasksInCell = String(gridSlice[r][c]).split('|');

        // C'est ici que la magie opère : On reconstruit la chaîne pour le frontend
        let newTasksInCell = tasksInCell.map(t => {
          if (!t.trim()) return t;
          let parts = t.split('@');
          let baseAbbr = parts[0].trim();
          let ampm = (parts.length >= 2 && (parts[1] === "AM" || parts[1] === "PM")) ? parts[1] : "";

          let status = (avancData[id] && avancData[id][baseAbbr]) ? avancData[id][baseAbbr] : "";
          let note = (notesData[id] && notesData[id][baseAbbr]) ? notesData[id][baseAbbr] : "";

          let res = baseAbbr;
          if (ampm) res += `@${ampm}`;
          if (status || note) res += `@${status}`; // On inclut le statut (même vide) si une note suit
          if (note) res += `@${note}`;
          return res;
        });
        gridSlice[r][c] = newTasksInCell.join('|');
      }
    }

    planningRows.push({
      id: id,
      status: gridMeta[r][1] || "",
      comment: gridMeta[r][2] || "",
      tasks: gridSlice[r],
      sheetRowIdx: r + 7  // FIX E5: row's 1-based sheet index — lets client-side save calls skip the full column-A scan
    });
  }

  // 4. RÉSERVES (Non modifié)
  // Replace section 4 in your gsGetPlanningWindow function with this:
  const repairs = {};
  if (shPlanReserves) {
    const lastRowPlanRes = shPlanReserves.getLastRow();
    if (lastRowPlanRes >= 7) {
      const gridMetaRes = shPlanReserves.getRange(7, 1, lastRowPlanRes - 6, 1).getValues();
      const gridSliceRes = shPlanReserves.getRange(7, colStartAbs, lastRowPlanRes - 6, windowSize).getValues();
      for (let r = 0; r < gridMetaRes.length; r++) {
        const id = gridMetaRes[r][0];
        if (!id || !logementsMeta[id]) continue;
        for (let c = 0; c < gridSliceRes[r].length; c++) {
          let cellVal = gridSliceRes[r][c].toString().trim();
          if (cellVal !== "") {
            let items = cellVal.split('|').map(i => i.trim()).filter(i => i !== "");

            // SECURITY: Hide any Autocontrôles ('A-') if the user is a client or in client view
            if (isClient) {
              items = items.filter(item => !item.startsWith('A-'));
            }

            if (items.length > 0) {
              const dateISO = headers.dates[c];
              if (!repairs[id]) repairs[id] = {};
              repairs[id][dateISO] = items;
            }
          }
        }
      }
    }
  }

  return { ok: true, window: { start: startDateStr, end: endDateStr }, headers: headers, logements: logementsMeta, planning: planningRows, repairs: repairs, notes: notesData };
}

function emptyResult(start, end) {
  return { ok: false, window: { start, end }, headers: {}, logements: {}, planning: [], repairs: {}, notes: {} };
}

// =========================================================
// Extracted from gsGetPlanningWindow's section "1. MÉTADONNÉES LOGEMENTS"
// so gsGetLogementsStructure() below can reuse the exact same parsing
// without also pulling in a date window. Behavior is unchanged — same
// column mapping per view, same batimentFilter support.
// =========================================================
function _buildLogementsMeta(shSource, view, batimentFilter) {
  const logementsMeta = {};
  const lastRowSource = shSource.getLastRow();
  if (lastRowSource >= 7) {
    const src = shSource.getRange(7, 2, lastRowSource - 6, 13).getValues();
    src.forEach(row => {
      const id = row[0];
      const bat = row[2];
      if (!id || (batimentFilter && bat !== batimentFilter)) return;

      let meta = { id: id, batiment: row[2], hall: row[3] };
      if (view === 'communs') {
        meta.etage = row[4];
        const colG = row[5] ? String(row[5]).trim() : "";
        const colH = row[6] ? String(row[6]).trim() : "";
        let desc = colG;
        if (colH !== "") {
          const fNum = parseInt(colH, 10);
          desc += " - " + (!isNaN(fNum) ? String(fNum).padStart(2, '0') : colH);
        }
        meta.description_part1 = colG; meta.description_part2 = colH; meta.description = desc.trim();
      } else if (view === 'facades') {
        meta.orientation = row[4]; meta.type = row[7];
        const colG = row[5] ? String(row[5]).trim() : "";
        const colH = row[6] ? String(row[6]).trim() : "";
        const gNum = parseInt(colG, 10);
        meta.trame_part1 = colG;
        meta.trame = ("Trame " + (!isNaN(gNum) ? String(gNum).padStart(2, '0') : colG) + (colH ? " - " + colH : "")).trim();
        meta.partie = colH;
        meta.trame_filter_val = ("Trame " + (!isNaN(gNum) ? String(gNum).padStart(2, '0') : colG)).trim();
      } else {
        meta.etage = row[4]; meta.empilement = row[5]; meta.porte = row[6]; meta.type = row[7];
        meta.type1 = row[7] ? "L" + String(row[7]).trim() : "";
        meta.config = row[8]; meta.surface = row[9]; meta.nom = row[10]; meta.prenom = row[11];
      }
      logementsMeta[id] = meta;
    });
  }
  return logementsMeta;
}

// =========================================================
// Structure complète (Bâtiment/Hall/Étage-Orientation/Porte-Description-
// Trame/ID, ...) d'une vue, SANS fenêtre de dates et SANS filtre Bâtiment
// — contrairement à gsGetPlanningWindow(), qui peut être restreint par
// batimentFilter (l'utilisateur peut avoir un filtre Bâtiment actif sur la
// grille). Utilisée par le sélecteur en cascade de la correction de
// référence ("Corriger" -> "La référence") côté Planning, pour que la
// liste des cibles proposées ne dépende jamais d'un filtre d'affichage.
// Retourne un TABLEAU (Object.values du dict interne), pour un usage
// direct avec .filter()/.map() côté client — même forme que rawData[view]
// dans EDL_Script_2.txt.
// =========================================================
function gsGetLogementsStructure(token, projectId, view) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");

  const names = getSheetNames(view);
  const ssSource = SpreadsheetApp.openById(BATIMENTS_SS_ID);
  const shSource = ssSource.getSheetByName(names.source);
  if (!shSource) return [];

  const logementsMeta = _buildLogementsMeta(shSource, view, null);
  return Object.values(logementsMeta);
}

// =========================================================
// 2. Récupère les bornes temporelles réelles du projet (première et dernière date du planning)
// =========================================================

function getProjectDateBounds(token) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");

  const ssPlanning = SpreadsheetApp.openById(PLANNING_SS_ID);
  const shPlan = ssPlanning.getSheetByName('Planning');

  const lastCol = shPlan.getLastColumn();
  if (lastCol < 8) return { start: new Date().toISOString(), end: new Date().toISOString() };

  // On récupère la ligne 2 (où sont vos dates) de la colonne 8 à la fin
  const dateValues = shPlan.getRange(2, 8, 1, lastCol - 7).getValues()[0];

  return {
    start: new Date(dateValues[0]).toISOString(),
    end: new Date(dateValues[dateValues.length - 1]).toISOString()
  };
}

// =========================================================
// 3. Fetches tasks from the "Taches" sheet starting from Row 7, Col B.
// =========================================================

function gsGetTasks(token) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");
  try {
    const id = PLANNING_SS_ID;
    const ss = SpreadsheetApp.openById(id);
    const sheet = ss.getSheetByName('Taches');
    if (!sheet) return [];

    const lastRow = sheet.getLastRow();
    if (lastRow < 7) return [];

    // On récupère de la colonne A (1) à I (9)
    const data = sheet.getRange(7, 1, lastRow - 6, 9).getValues();

    return data.map((row, index) => ({
      rowIdx: index + 7,
      abbr: row[1],        // Col B (Index 1)
      type: row[2],        // Col C (Index 2)
      equipe: row[3],      // Col D (Index 3)
      desc: row[4],        // Col E (Index 4)
      descCourte: row[5],   // Col F (Index 5)
      bgColor: row[6],     // Col G (Index 6)
      duree: row[7],       // Col H (Index 7)
      unite: row[8]        // Col I (Index 8)
    })).filter(t => t.abbr && t.abbr.toString().trim() !== ""); 

  } catch (e) {
    console.error("Erreur gsGetTasks: " + e.message);
    return [];
  }
}

// =========================================================
// 3. Saves or Updates a task
// =========================================================

function gsSaveTask(token, taskData) {
  assertCanEdit_(token, taskData.projectId || null);

  const id = PLANNING_SS_ID;
  const ss = SpreadsheetApp.openById(id);
  const sheetTaches = ss.getSheetByName('Taches');

  const newAbbr = taskData.abbr.toString().trim();
  const newDescCourte = taskData.descCourte.toString().trim();
  const rowIdx = taskData.rowIdx ? parseInt(taskData.rowIdx) : null;

  // ABREVIATION VALIDATION
  if (newAbbr.includes('|') || newAbbr.includes('@')) {
    return { success: false, isUserNotice: true, message: "L'abréviation ne peut pas contenir les caractères '|' ou '@'." };
  }

  // --- 1. VÉRIFICATION DES DOUBLONS ---
  const lastRowTaches = sheetTaches.getLastRow();
  if (lastRowTaches >= 7) {
    // On récupère de la colonne B (2) à F (6) pour avoir l'abréviation et la description courte
    const existingData = sheetTaches.getRange(7, 2, lastRowTaches - 6, 5).getValues();

    for (let i = 0; i < existingData.length; i++) {
      const currentRow = i + 7;

      // Si on est en mode édition, on ignore la ligne qu'on est en train de modifier
      if (rowIdx && currentRow === rowIdx) continue; 

      const existingAbbr = existingData[i][0].toString().trim(); // Col B (Abréviation)
      const existingDesc = existingData[i][4].toString().trim(); // Col F (Desc Courte)

      // Vérification insensible à la casse
      if (existingAbbr.toLowerCase() === newAbbr.toLowerCase()) {
        return { success: false, isUserNotice: true, message: "L'abréviation '" + newAbbr + "' est déjà utilisée par une autre tâche." };
      }
      if (existingDesc.toLowerCase() === newDescCourte.toLowerCase()) {
        return { success: false, isUserNotice: true, message: "La description courte '" + newDescCourte + "' est déjà utilisée par une autre tâche." };
      }
    }
  }

  // --- 2. MISE À JOUR EN CASCADE (PLANNING) ---
  if (rowIdx) {
    const oldAbbr = sheetTaches.getRange(rowIdx, 2).getValue().toString().trim();
    const oldDiscipline = sheetTaches.getRange(rowIdx, 3).getValue().toString().trim();

    // VERROU : Empêcher le changement de discipline si c'est la dernière tâche EDL/OPR
    const upperOldDisc = oldDiscipline.toUpperCase();
    const upperNewDisc = taskData.type.toString().trim().toUpperCase();

    if ((upperOldDisc === "EDL" || upperOldDisc === "OPR") && upperOldDisc !== upperNewDisc) {
      if (lastRowTaches >= 7) {
        const allDisciplines = sheetTaches.getRange(7, 3, lastRowTaches - 6, 1).getValues();
        let count = 0;
        for (let i = 0; i < allDisciplines.length; i++) {
          if (allDisciplines[i][0].toString().trim().toUpperCase() === upperOldDisc) count++;
        }
        if (count <= 1) {
          return { success: false, isUserNotice: true, message: "Action impossible : Vous ne pouvez pas modifier le corps d'état de cette tâche car c'est la dernière associée à '" + oldDiscipline + "'." };
        }
      }
    }

    // CASCADE : Si l'abréviation a changé, on met à jour le planning en respectant les séparateurs "|"
    if (oldAbbr !== "" && oldAbbr !== newAbbr) {
      const planSheetNames = ['Planning', 'Planning Communs', 'Planning Facades']; // Les 3 vues

      planSheetNames.forEach(sheetName => {
        const sheetPlan = ss.getSheetByName(sheetName);
        if (!sheetPlan) return; // Ignore si l'onglet n'existe pas

        const lastRowPlan = sheetPlan.getLastRow();
        const lastColPlan = sheetPlan.getLastColumn();

        if (lastRowPlan >= 7 && lastColPlan >= 8) {
          const planRange = sheetPlan.getRange(7, 8, lastRowPlan - 6, lastColPlan - 7);
          const planData = planRange.getValues();
          let updateCount = 0;

          for (let r = 0; r < planData.length; r++) {
            for (let c = 0; c < planData[r].length; c++) {
              let cellVal = planData[r][c].toString().trim();
              if (cellVal !== "") {
                let parts = cellVal.split('|');
                let changed = false;

                for (let p = 0; p < parts.length; p++) {
                  // Separate the base task from its modifier (e.g., "PLOMB" and "@AM")
                  let baseTask = parts[p].split('@')[0].trim();
                  let modifier = parts[p].includes('@') ? '@' + parts[p].split('@')[1].trim() : '';

                  if (baseTask === oldAbbr) {
                    parts[p] = newAbbr + modifier; // Applies the new name but keeps @AM/@PM
                    changed = true;
                  }
                }

                if (changed) {
                  planData[r][c] = parts.join('|');
                  updateCount++;
                }
              }
            }
          }
          if (updateCount > 0) planRange.setValues(planData);
        }
      });
    }
  }

  // --- 3. MISE À JOUR SYNCHRONISÉE DES CYCLES ---
  if (taskData.rowIdx && taskData.oldAbbr) {
    const sheetCycles = ss.getSheetByName('Cycles');
    const lastRow = sheetCycles.getLastRow();

    // On récupère la nouvelle couleur définie pour la tâche
    const newColor = taskData.bgColor || taskData.couleur || "#e2e8f0";

    if (lastRow >= 7) {
      const range = sheetCycles.getRange(7, 2, lastRow - 6, 4); // Nom, Desc, JSON, Aperçu
      const values = range.getValues();
      let modified = false;

      for (let i = 0; i < values.length; i++) {
        let sequenceJson = values[i][2];
        if (!sequenceJson) continue;

        try {
          let sequence = JSON.parse(sequenceJson);
          let cycleChanged = false;

          sequence = sequence.map(step => {
            // Si cette étape du cycle correspond à la tâche qu'on modifie
            if (step.taskAbbr === taskData.oldAbbr) {
              cycleChanged = true;
              return {
                ...step,
                taskAbbr: taskData.abbr, // Nouvelle Abrév.
                duree: taskData.duree,    // Nouvelle Durée
                color: newColor           // MISE À JOUR DE LA COULEUR ICI
              };
            }
            return step;
          });

          if (cycleChanged) {
            values[i][2] = JSON.stringify(sequence);
            // Mise à jour de l'aperçu visuel (index 3)
            values[i][3] = sequence.map(s => s.taskAbbr).join(" > ");
            modified = true;
          }
        } catch (e) {
          console.error("Erreur parsing JSON cycle ligne " + (i+7));
        }
      }

      if (modified) {
        range.setValues(values);
      }
    }
  }

  // --- 4. ENREGISTREMENT ---
  const rowValues = [newAbbr, taskData.type, taskData.equipe, taskData.desc, taskData.descCourte, taskData.couleur || taskData.bgColor, taskData.duree, taskData.unite];

  if (rowIdx) {
    sheetTaches.getRange(rowIdx, 2, 1, 8).setValues([rowValues]);
  } else {
    let targetRow = Math.max(sheetTaches.getLastRow() + 1, 7);
    sheetTaches.getRange(targetRow, 2, 1, 8).setValues([rowValues]);
  }

  try {
    syncTaskHeaders(taskData.oldAbbr, taskData.abbr);
  } catch (e) {
    console.error("Erreur de synchro des colonnes : " + e.message);
  }

  return true;
}

// =========================================================
// 4. Supprime une tâche et ses colonnes associées dans Recap et Avancement
// =========================================================

function gsDeleteTask(token, rowIdx, forceDelete = false, colsCacheJson) {
  assertCanEdit_(token, null);

  const ss = SpreadsheetApp.openById(PLANNING_SS_ID);
  const sheetTaches = ss.getSheetByName('Taches');
  const planSheetNames = ['Planning', 'Planning Communs', 'Planning Facades'];

  const row = parseInt(rowIdx);

  // Récupération de l'abréviation et de la discipline
  const rowData      = sheetTaches.getRange(row, 2, 1, 2).getValues()[0];
  const abbrToDelete = rowData[0].toString().trim();
  const discipline   = rowData[1].toString().trim();
  const upperDisc    = discipline.toUpperCase();

  // Si on est en mode "Force Delete" (Le client a validé l'alerte de suppression de données)
  if (forceDelete && colsCacheJson) {
    try {
      const colsCache = JSON.parse(colsCacheJson);
      colsCache.forEach(item => {
        const sh = ss.getSheetByName(item.sheetName);
        if (sh) sh.deleteColumn(item.col);
      });
      sheetTaches.deleteRow(row);
      return true;
    } catch(e) {
      // En cas de cache malformé, on continue vers les vérifications standards
    }
  }

  // --- 1. VÉRIFICATIONS DE SÉCURITÉ ---

  // A. Vérification de la protection Système (EDL / OPR)
  if (upperDisc === "EDL" || upperDisc === "OPR") {
    const lastRowTaches = sheetTaches.getLastRow();
    if (lastRowTaches >= 7) {
      const allDisciplines = sheetTaches.getRange(7, 3, lastRowTaches - 6, 1).getValues();
      let count = 0;
      for (let i = 0; i < allDisciplines.length; i++) {
        if (allDisciplines[i][0].toString().trim().toUpperCase() === upperDisc) count++;
      }
      if (count <= 1) return { success: false, isUserNotice: true, message: "Il doit rester au moins une tâche associée à la discipline <b>" + discipline + "</b>." };
    }
  }

  // B. NOUVEAU : Vérification présence dans les Cycles
  const sheetCycles = ss.getSheetByName('Cycles');
  if (sheetCycles) {
    const lastRowCycles = sheetCycles.getLastRow();
    if (lastRowCycles >= 7) {
      // On récupère le Nom (Col B / index 0) et le JSON de la séquence (Col D / index 2)
      const cyclesData = sheetCycles.getRange(7, 2, lastRowCycles - 6, 3).getValues();
      let usedInCycles = [];

      for (let i = 0; i < cyclesData.length; i++) {
        const cycleName = cyclesData[i][0].toString().trim();
        const sequenceJson = cyclesData[i][2];

        if (sequenceJson) {
          try {
            // On décode le JSON de la séquence pour vérifier les tâches à l'intérieur
            const sequence = JSON.parse(sequenceJson);
            // On cherche si au moins une étape utilise notre abréviation
            const isUsed = sequence.some(step => step.taskAbbr === abbrToDelete);

            if (isUsed) {
              usedInCycles.push(cycleName);
            }
          } catch (e) {
            console.warn("JSON invalide ignoré lors de la vérification de suppression sur le cycle :", cycleName);
          }
        }
      }

      // Si la tâche est utilisée dans au moins un cycle, on bloque tout
      if (usedInCycles.length > 0) {
        return { success: false, isUserNotice: true, message: `La tâche <b>${abbrToDelete}</b> fait partie des cycles suivants : <b>${usedInCycles.join(", ")}</b>.<br><br>Veuillez d'abord la retirer de ces cycles.` };
      }
    }
  }

  // C. Vérification présence dans TOUS les plannings
  planSheetNames.forEach(sheetName => {
    const sheetPlan = ss.getSheetByName(sheetName);
    if (!sheetPlan) return;
    const lastRowPlan = sheetPlan.getLastRow();
    const lastColPlan = sheetPlan.getLastColumn();
    if (lastRowPlan >= 7 && lastColPlan >= 8) {
      const planData = sheetPlan.getRange(7, 8, lastRowPlan - 6, lastColPlan - 7).getValues();
      for (let r = 0; r < planData.length; r++) {
        for (let c = 0; c < planData[r].length; c++) {
          if (planData[r][c].toString().split('|').includes(abbrToDelete)) {
            return { success: false, isUserNotice: true, message: `La tâche <b>${abbrToDelete}</b> est actuellement utilisée dans le planning <b>${sheetName}</b>.` };
          }
        }
      }
    }
  });

  // --- 2. GESTION DES COLONNES RECAP, AVANCEMENT ET NOTES ---
  const sheetsToClean = ['Recap', 'Recap Communs', 'Recap Facades', 'avancement', 'avancement Communs', 'Avancement Facades', 'Notes', 'Notes Communs', 'Notes Facades'];
  let columnsToDelete  = [];
  let foundDataLocations = [];

  sheetsToClean.forEach(name => {
    const sh = ss.getSheetByName(name);
    if (!sh) return;
    const lastCol = sh.getLastColumn();
    const lastRow = sh.getLastRow();
    if (lastCol < 2 || lastRow < 6) return;

    const allData  = sh.getRange(6, 2, Math.max(lastRow - 5, 1), lastCol - 1).getValues();
    const headers  = allData[0];
    const colIdx   = headers.indexOf(abbrToDelete);
    if (colIdx === -1) return;

    const colNumber = colIdx + 2;

    if (!forceDelete && allData.length > 1) {
      const hasData = allData.slice(1).some(r => r[colIdx] !== "" && r[colIdx] !== null);
      if (hasData) foundDataLocations.push(`Feuille "${name}" (Colonne ${abbrToDelete})`);
    }
    columnsToDelete.push({ sheet: sh, sheetName: name, col: colNumber });
  });

  if (foundDataLocations.length > 0 && !forceDelete) {
    const colsCache = JSON.stringify(columnsToDelete.map(c => ({ sheetName: c.sheetName, col: c.col })));
    return { success: false, isUserNotice: true, isDataFound: true, locations: foundDataLocations.join(" et "), colsCache: colsCache };
  }

  // --- 3. EXÉCUTION DE LA SUPPRESSION ---
  columnsToDelete.forEach(item => item.sheet.deleteColumn(item.col));
  sheetTaches.deleteRow(row);
  return true;
}

// =========================================================
// 5. DISCIPLINE MANAGEMENT (Backend)
// =========================================================

function gsGetDisciplines(token) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");
  try {
    const id = PLANNING_SS_ID;
    const ss = SpreadsheetApp.openById(id);
    const sheet = ss.getSheetByName('Disciplines');

    if (!sheet) return [{ name: "Erreur : Onglet 'Disciplines' introuvable" }];

    const lastRow = sheet.getLastRow();
    // Si la dernière ligne est < 7, il n'y a pas de données
    if (lastRow < 7) return [];

    // On lit à partir de la ligne 7, colonne 2 (B), sur (lastRow - 6) lignes
    const values = sheet.getRange(7, 2, lastRow - 6, 1).getValues();
    const result = [];

    for (let i = 0; i < values.length; i++) {
      const cellValue = values[i][0];
      // On vérifie que la cellule n'est pas vide
      if (cellValue && cellValue.toString().trim() !== "") {
        result.push({
          rowIdx: i + 7, // On garde l'index réel de la ligne pour la suppression/édition
          name: cellValue.toString().trim()
        });
      }
    }

    return result;

  } catch (e) {
    console.error("Erreur gsGetDisciplines: " + e.message);
    return [{ name: "Erreur Serveur : " + e.message }];
  }
}

// =========================================================
// SAUVEGARDE RAPIDE (Met à jour Disciplines et libère l'UI)
// =========================================================
function gsSaveDiscipline(token, newName, rowIdx) {
  assertCanEdit_(token, null);

  const id1 = PLANNING_SS_ID;
  const ss1 = SpreadsheetApp.openById(id1);
  const sheetDisc = ss1.getSheetByName('Disciplines');
  const cleanName = newName.trim();
  const lastRow = sheetDisc.getLastRow();

  // --- 1. VÉRIFICATION DES DOUBLONS ---
  let existingNames = [];
  if (lastRow >= 7) {
    existingNames = sheetDisc.getRange(7, 2, lastRow - 6, 1).getValues().flat();
  }

  const isDuplicate = existingNames.some((name, index) => {
    if (rowIdx && (index + 7) === parseInt(rowIdx)) return false;
    return name.toString().toLowerCase() === cleanName.toLowerCase();
  });

  if (isDuplicate) {
    return { success: false, isUserNotice: true, message: "Cette discipline existe déjà." };
  }

  let oldName = null;

  // --- 2. ENREGISTREMENT ---
  if (rowIdx) {
    // Mode Édition : on stocke l'ancien nom pour la cascade
    oldName = sheetDisc.getRange(parseInt(rowIdx), 2).getValue().toString().trim();
    const upperOldName = oldName.toUpperCase();

    if (upperOldName === "EDL" || upperOldName === "OPR") {
      return { success: false, isUserNotice: true, message: "Action impossible : La discipline <b>" + oldName + "</b> est protégée." };
    }
    sheetDisc.getRange(parseInt(rowIdx), 2).setValue(cleanName);
  } else {
    // Mode Ajout
    let targetRow = (lastRow < 7) ? 7 : lastRow + 1;
    sheetDisc.getRange(targetRow, 2).setValue(cleanName);
  }

  // --- 3. TRI AUTOMATIQUE ---
  const newLastRow = sheetDisc.getLastRow();
  if (newLastRow >= 7) {
    sheetDisc.getRange(7, 2, newLastRow - 6, 1).sort({column: 2, ascending: true});
  }

  // On renvoie l'ancien et le nouveau nom pour déclencher la cascade en arrière-plan
  return { oldName: oldName, newName: cleanName };
}


// =========================================================
// MISE À JOUR EN CASCADE (Exécutée de manière asynchrone)
// =========================================================
function gsCascadeDisciplineUpdate(token, oldName, newName) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");
  if (!oldName || !newName || oldName === newName) return false;

  // --- A. ONGLET "Taches" -> COLONNE C (Index 3), LIGNE 7+ ---
  const ssPlanning = SpreadsheetApp.openById(PLANNING_SS_ID);
  const sheetTaches = ssPlanning.getSheetByName('Taches');
  if (sheetTaches) {
    const lastRowTaches = sheetTaches.getLastRow();
    if (lastRowTaches >= 7) {
      const rangeTaches = sheetTaches.getRange(7, 3, lastRowTaches - 6, 1); // Colonne C = 3 
      const dataTaches = rangeTaches.getValues();
      let changedTaches = false;

      for (let i = 0; i < dataTaches.length; i++) {
        if (dataTaches[i][0].toString().trim() === oldName) {
          dataTaches[i][0] = newName;
          changedTaches = true;
        }
      }
      if (changedTaches) rangeTaches.setValues(dataTaches);
    }
  }

  // --- B. CLASSEUR DES RÉSERVES -> COLONNE D (Index 4), LIGNE 7+ ---
  // On ouvre le second classeur grâce à RESERVES_SS_ID (RESERVES_SPREADSHEET_ID)
  const ssReserves = SpreadsheetApp.openById(RESERVES_SS_ID); 
  const targetSheets = [
    "AutoControle", "Reserves", 
    "AutoControle Communs", "Reserves Communs", 
    "AutoControle Facades", "Reserves Facades"
  ];

  targetSheets.forEach(sheetName => {
    const currentSheet = ssReserves.getSheetByName(sheetName);
    if (currentSheet) {
      const lastRowRep = currentSheet.getLastRow();
      if (lastRowRep >= 7) {
        const rangeRep = currentSheet.getRange(7, 4, lastRowRep - 6, 1); // Colonne D = 4
        const dataRep = rangeRep.getValues();
        let changedRep = false;

        for (let j = 0; j < dataRep.length; j++) {
          if (dataRep[j][0].toString().trim() === oldName) {
            dataRep[j][0] = newName;
            changedRep = true;
          }
        }
        if (changedRep) rangeRep.setValues(dataRep);
      }
    }
  });

  return true;
}

function gsDeleteDiscipline(token, rowIdx) {
  assertCanEdit_(token, null);

  const id1 = PLANNING_SS_ID;
  const ss1 = SpreadsheetApp.openById(id1);
  const sheetDisc = ss1.getSheetByName('Disciplines');
  const sheetTaches = ss1.getSheetByName('Taches');

  // 1. Récupérer le nom de la discipline à supprimer
  const disciplineName = sheetDisc.getRange(parseInt(rowIdx), 2).getValue().toString().trim();
  const upperName = disciplineName.toUpperCase();

  // VERROU 1 : Protection stricte EDL et OPR
  if (upperName === "EDL" || upperName === "OPR") {
    return { success: false, isUserNotice: true, message: "Action impossible : La discipline <b>" + disciplineName + "</b> est requise par le système et ne peut pas être supprimée." };
  }

  // 2. Vérifier si elle est utilisée dans "Taches"
  const lastRowTaches = sheetTaches.getLastRow();
  if (lastRowTaches >= 7) {
    // La discipline est en colonne C (index 3) dans Taches
    const dataTaches = sheetTaches.getRange(7, 3, lastRowTaches - 6, 1).getValues(); 
    const isUsedInTaches = dataTaches.some(row => row[0].toString().trim() === disciplineName);
    if (isUsedInTaches) {
      return { success: false, isUserNotice: true, message: "Impossible de supprimer : cette discipline est actuellement utilisée dans la liste des Tâches." };
    }
  }

  // 3. OPTIMISATION : Vérification dans l'onglet de synthèse des Réserves
  const id2 = RESERVES_SS_ID;
  const ss2 = SpreadsheetApp.openById(id2);
  const summarySheet = ss2.getSheetByName('Summary');

  if (!summarySheet) {
    throw new Error("Erreur Serveur : L'onglet 'Disciplines_Summary' est introuvable dans le classeur des Réserves.");
  }

  // On récupère toutes les données de la synthèse d'un seul coup (1 appel API au lieu de 6)
  const summaryData = summarySheet.getDataRange().getValues();
  const usedInSheets = [];

  // Mappage des index de colonnes (0 à 5) avec le nom réel des onglets
  const columnToSheetName = [
    "AutoControle",           // Colonne A (0)
    "Reserves",               // Colonne B (1)
    "AutoControle Communs",   // Colonne C (2)
    "Reserves Communs",       // Colonne D (3)
    "AutoControle Facades",   // Colonne E (4)
    "Reserves Facades"        // Colonne F (5)
  ];

  // On scanne les 6 colonnes de la matrice récupérée
  for (let col = 0; col < 6; col++) {
    let foundInColumn = false;
    for (let row = 0; row < summaryData.length; row++) {
      if (summaryData[row][col] && summaryData[row][col].toString().trim() === disciplineName) {
        foundInColumn = true;
        break; // Pas besoin de continuer à chercher dans cette colonne
      }
    }
    // Si trouvée, on mémorise le nom de l'onglet
    if (foundInColumn) {
      usedInSheets.push(columnToSheetName[col]);
    }
  }

  // S'il y a des occurrences, on bloque et on liste tous les onglets concernés
  if (usedInSheets.length > 0) {
    return { success: false, isUserNotice: true, message: "Impossible de supprimer : la discipline <b>" + disciplineName + "</b> est encore utilisée dans : " + usedInSheets.join(", ") + "." };
  }

  // 4. Si non utilisée nulle part, on supprime définitivement
  sheetDisc.deleteRow(parseInt(rowIdx));
  return true;
}

// =========================================================
// 6. Réorganise l'ordre des tâches dans la feuille "Taches"
// =========================================================

function gsReorderTasks(token, orderedRowIndices) {
  assertCanEdit_(token, null);
  try {
    const id = PLANNING_SS_ID;
    const ss = SpreadsheetApp.openById(id);
    const sheetTaches = ss.getSheetByName('Taches');

    const lastRow = sheetTaches.getLastRow();
    if (lastRow < 7) return false;

    // On récupère de la colonne A (1) à I (9), à partir de la ligne 7
    const range = sheetTaches.getRange(7, 1, lastRow - 6, 9);
    const currentData = range.getValues();

    // On reconstruit le tableau de données dans le nouvel ordre
    const newData = [];

    for (let i = 0; i < orderedRowIndices.length; i++) {
      const oldRowIdx = orderedRowIndices[i];
      // L'index dans le tableau JS est (Row - 7)
      const arrayIdx = oldRowIdx - 7; 

      if (currentData[arrayIdx]) {
        newData.push(currentData[arrayIdx]);
      }
    }

    // Sécurité : On vérifie qu'on n'a pas perdu de données en route
    if (newData.length === currentData.length) {
      range.setValues(newData);
      return true;
    } else {
      throw new Error("Erreur d'intégrité : le nombre de lignes ne correspond pas.");
    }

  } catch (e) {
    console.error("Erreur gsReorderTasks: " + e.message);
    throw new Error(e.message);
  }
}

// =========================================================
// 7. GESTION DES CYCLES (BACKEND)
// =========================================================

function gsGetCycles(token) {
  const user = getSession_(token);
  if (!user) throw new Error("Sécurité : Session expirée.");
  try {
    const id = PLANNING_SS_ID;
    const ss = SpreadsheetApp.openById(id);
    const sheet = ss.getSheetByName('Cycles');
    if (!sheet) return [];

    const lastRow = sheet.getLastRow();
    if (lastRow < 7) return [];

    // Récupération de B (2) à E (5) : Nom, Description, Séquence JSON, Aperçu
    const data = sheet.getRange(7, 2, lastRow - 6, 4).getValues();

    return data.map((row, index) => {
      let sequence = [];
      try {
        if (row[2]) {
          sequence = normalizeCycleSequence(JSON.parse(row[2]));
        }
      } catch(e) { console.warn("JSON invalide pour le cycle ligne " + (index+7)); }

      return {
        rowIdx: index + 7,
        nom: row[0],
        description: row[1],
        sequence: sequence,
        apercu: row[3]
      };
    }).filter(c => c.nom && c.nom.toString().trim() !== "");
  } catch (e) {
    console.error("Erreur gsGetCycles: " + e.message);
    return [];
  }
}

function gsSaveCycle(token, cycleData) {
  assertCanEdit_(token, null);

  const id = PLANNING_SS_ID;
  const ss = SpreadsheetApp.openById(id);
  const sheet = ss.getSheetByName('Cycles');

  const cleanNom = cycleData.nom.toString().trim();
  const rowIdx = cycleData.rowIdx ? parseInt(cycleData.rowIdx) : null;
  cycleData.sequence = normalizeCycleSequence(cycleData.sequence);
  const sequenceJSON = JSON.stringify(cycleData.sequence);

  // Générer un aperçu visuel texte simple (ex: PLB > ELEC > PEIN)
  const apercu = cycleData.sequence.map(s => s.taskAbbr).join(" > ")

  // 1. Vérification des doublons de nom
  const lastRow = sheet.getLastRow();
  if (lastRow >= 7) {
    const existingNames = sheet.getRange(7, 2, lastRow - 6, 1).getValues();
    for (let i = 0; i < existingNames.length; i++) {
      if (rowIdx && (i + 7) === rowIdx) continue;
      if (existingNames[i][0].toString().trim().toLowerCase() === cleanNom.toLowerCase()) {
        return { success: false, isUserNotice: true, message: "Un cycle nommé '" + cleanNom + "' existe déjà." };
      }
    }
  }

  const rowValues = [cleanNom, cycleData.description, sequenceJSON, apercu];

  // 2. Enregistrement
  if (rowIdx) {
    sheet.getRange(rowIdx, 2, 1, 4).setValues([rowValues]);
  } else {
    let targetRow = Math.max(lastRow + 1, 7);
    sheet.getRange(targetRow, 2, 1, 4).setValues([rowValues]);
  }
  return true;
}

function gsDeleteCycle(token, rowIdx) {
  assertCanEdit_(token, null);

  const id = PLANNING_SS_ID;
  const ss = SpreadsheetApp.openById(id);
  const sheet = ss.getSheetByName('Cycles');

  sheet.deleteRow(parseInt(rowIdx));
  return true;
}

// =========================================================
// 8. Synchronise les en-têtes des feuilles Recap et Avancement
// =========================================================

function syncTaskHeaders(oldAbbr, newAbbr) {

  const id = PLANNING_SS_ID;
  const ss = SpreadsheetApp.openById(id);
  const sheetsToSync = ['Recap', 'Recap Communs', 'Recap Facades', 'avancement', 'avancement Communs', 'Avancement Facades', 'Notes', 'Notes Communs', 'Notes Facades'];
  const HEADER_ROW = 6; // Ligne où se trouvent les abréviations
  const START_COL = 2;  // On commence à chercher à partir de la colonne B (A = IDs)

  sheetsToSync.forEach(sheetName => {
    const sheet = ss.getSheetByName(sheetName);
    if (!sheet) return;

    const lastCol = Math.max(sheet.getLastColumn(), START_COL);
    const headersRange = sheet.getRange(HEADER_ROW, START_COL, 1, lastCol);
    const headers = headersRange.getValues()[0];

    let foundIndex = -1;
    if (oldAbbr) {
      // On cherche l'ancienne abréviation pour la mettre à jour
      foundIndex = headers.indexOf(oldAbbr);
    }

    if (foundIndex !== -1) {
      // CAS 1 : Mise à jour d'une tâche existante
      sheet.getRange(HEADER_ROW, START_COL + foundIndex).setValue(newAbbr);
    } else {
      // CAS 2 : Nouvelle tâche (ou ancienne non trouvée)
      // On vérifie d'abord si newAbbr n'existe pas déjà
      if (headers.indexOf(newAbbr) === -1) {
        const nextCol = sheet.getLastColumn() + 1;
        sheet.getRange(HEADER_ROW, nextCol).setValue(newAbbr);
      }
    }
  });
}

